			unlock = {
				{ type = "quest", id = 3801 },
			},
			text = [=[To the rare visitor who can see him, Franclorn tells the story of his people without ornament. He believed he had no choice. He endured the ruin of {link:ruins-of-thaurissan}Thaurissan{/link} and stood beside his king. He and his builders worked without rest to raise a city that no {link:dwarves}dwarf{/link} before or after could surpass, and all the while he watched his kin change. When the last stone of the Spire was set, he found he no longer wished to live among them. The tomb where his spirit stands was their thanks.]=],
